class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        if len(s1) + len(s2) != len(s3):
            return False
        n = len(s2)
        dp = [False] * (n + 1)
        dp[n] = True
        for i in range(len(s1), -1, -1):
            for j in range(n, -1, -1):
                if i == len(s1) and j == n:
                    continue
                k = i + j
                dp[j] = (i < len(s1) and s1[i] == s3[k] and dp[j]) or (
                    j < n and s2[j] == s3[k] and dp[j + 1]
                )
        return dp[0]

